from bisect import bisect_left
from typing import List

def maxDistance(side: int, points: List[List[int]], k: int) -> int:
    perim = 4 * side
    coords = []
    for x, y in points:
        if x == 0:
            c = y                  # left edge, going up from (0, 0)
        elif y == side:
            c = side + x           # top edge, going right
        elif x == side:
            c = 3 * side - y       # right edge, going down
        else:                      # y == 0
            c = 4 * side - x       # bottom edge, going left
        coords.append(c)
    coords.sort()
    n = len(coords)
    ext = coords + [c + perim for c in coords]

    def can_place(d: int) -> bool:
        for start in range(n):
            cur = start
            cnt = 1
            end = start + n          # indices must stay within one lap
            while cnt < k:
                nxt = bisect_left(ext, ext[cur] + d, cur + 1, end)
                if nxt == end:
                    break
                cur = nxt
                cnt += 1
            if cnt == k and ext[start] + perim - ext[cur] >= d:
                return True
        return False

    low, high = 0, side + 1          # low always feasible, high never feasible
    while low < high - 1:
        mid = (low + high) // 2
        if can_place(mid):
            low = mid
        else:
            high = mid
    return low
